import { keyframes } from '@emotion/react';
import styled from '@emotion/styled';

import { theme } from '../../../theme';
import { SKELETON_WAVE_HIGHLIGHT } from './SkeletonLoader.constants';
import type {
  SkeletonLoaderImageShape,
  SkeletonLoaderVariant,
} from './SkeletonLoader.types';

const waveAnimation = keyframes({
  from: {
    backgroundPosition: 'calc(0% - 50px) 0',
  },
  to: {
    backgroundPosition: '200% 0',
  },
});

const getBorderRadius = (
  variant: SkeletonLoaderVariant,
  imageShape: SkeletonLoaderImageShape,
): string => {
  if (variant === 'image') {
    return imageShape === 'circle'
      ? theme.borderRadius.full
      : theme.borderRadius['1'];
  }

  if (variant === 'circular') {
    return theme.borderRadius.full;
  }

  if (variant === 'text') {
    return theme.borderRadius['1'];
  }

  return theme.borderRadius['1'];
};

interface StyledProps {
  $imageShape: SkeletonLoaderImageShape;
  $variant: SkeletonLoaderVariant;
}

export const StyledSkeletonImage = styled.img({
  display: 'block',
  height: '100%',
  objectFit: 'cover',
  width: '100%',
});

export const StyledSkeletonLoader = styled('div')<StyledProps>(({
  $variant,
  $imageShape,
}) => {
  const surfaceColor = theme.colors.interfaceSurfacePrimary;
  const isImageVariant = $variant === 'image';

  return {
    position: 'relative',
    overflow: 'hidden',
    display: 'block',
    borderRadius: getBorderRadius($variant, $imageShape),
    backgroundColor: isImageVariant ? 'transparent' : surfaceColor,
    ...(!isImageVariant && {
      '&::after': {
        animation: `${waveAnimation} 1s linear infinite`,
        background: `linear-gradient(to right, ${surfaceColor}, ${SKELETON_WAVE_HIGHLIGHT}, ${surfaceColor})`,
        backgroundPosition: 'calc(0% - 50px) 0',
        backgroundRepeat: 'repeat-y',
        backgroundSize: '50px auto',
        content: '""',
        height: '100%',
        left: '-20%',
        position: 'absolute',
        top: 0,
        transform: 'skew(-10deg)',
        width: '140%',
      },
    }),
    '@media (prefers-reduced-motion: reduce)': {
      '&::after': {
        animation: 'none',
      },
    },
  };
});
